-- =====================================================================
--  Áreas Verdes · Límites delegacionales OFICIALES (KMZ 2026).
--  7 polígonos: geojson (para el mapa) + geom GEOMETRY SRID 0 (ST_Contains).
--  Además: columna derivada areas_verdes.delegacion_geo (delegación por
--  geometría) y su recálculo. Idempotente.
-- =====================================================================
SET NAMES utf8mb4;
USE portal_qro;

CREATE TABLE IF NOT EXISTS delegaciones_geo (
  id           SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  nombre       VARCHAR(120) NOT NULL,
  nombre_norm  VARCHAR(120) NOT NULL,
  geojson      LONGTEXT NOT NULL,
  geom         GEOMETRY NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_norm (nombre_norm)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM delegaciones_geo;
ALTER TABLE delegaciones_geo AUTO_INCREMENT = 1;

