-- Columna derivada por geometría (delegación real donde cae la coordenada) ---
ALTER TABLE areas_verdes ADD COLUMN IF NOT EXISTS delegacion_geo VARCHAR(120) NULL AFTER delegacion_norm;

-- Recalcular delegacion_geo con los polígonos oficiales (SRID 0, como secciones)
SET SESSION TRANSACTION ISOLATION LEVEL READ COMMITTED;
UPDATE areas_verdes av
  LEFT JOIN delegaciones_geo dg
    ON ST_Contains(ST_GeomFromWKB(ST_AsWKB(dg.geom),0),
                   ST_GeomFromText(CONCAT('POINT(', av.lng, ' ', av.lat, ')'), 0))
  SET av.delegacion_geo = dg.nombre
  WHERE av.lat IS NOT NULL AND av.lng IS NOT NULL;
